function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function money($n){return '$'.number_format((float)$n,0);}
function sb141d($m,$ep,$p=null){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json','Prefer: return=representation'],CURLOPT_TIMEOUT=>25]);if($p!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($p));$b=curl_exec($ch);curl_close($ch);$d=json_decode($b,true);return is_array($d)?$d:[];}
$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';if($action==='add'){$row=[['source_type'=>$_POST['source_type']??'fsbo','source_platform'=>$_POST['source_platform']??'manual','source_url'=>$_POST['source_url']??'','listing_title'=>$_POST['listing_title']??'','property_address'=>$_POST['property_address']??'','town'=>$_POST['town']??'','list_price'=>is_numeric($_POST['list_price']??0)?(float)$_POST['list_price']:0,'owner_name'=>$_POST['owner_name']??'','owner_phone'=>$_POST['owner_phone']??'','owner_email'=>$_POST['owner_email']??'','dnc_status'=>$_POST['dnc_status']??'unchecked','realtor_status'=>$_POST['realtor_status']??'unchecked','approval_status'=>$_POST['approval_status']??'source_review','notes'=>$_POST['notes']??'','status'=>'active','created_at'=>date('c'),'updated_at'=>date('c')]];sb141d('POST','seller_opportunity_sources',$row);$msg='Seller source added.';}else{$id=$_POST['id']??'';$status=$_POST['status']??'';if($id&&in_array($status,['source_review','approved','rejected','archived'],true)){sb141d('PATCH','seller_opportunity_sources?id=eq.'.rawurlencode($id),['approval_status'=>$status,'updated_at'=>date('c')]);$msg='Opportunity updated.';}}}
$rows=sb141d('GET','seller_opportunity_sources?select=*&status=eq.active&order=total_seller_score.desc,created_at.desc&limit=400');$briefs=sb141d('GET','seller_opportunity_briefings?select=*&order=created_at.desc&limit=5');$brief=$briefs[0]??[];$stats=['total'=>count($rows),'fsbo'=>0,'a'=>0,'b'=>0,'call'=>0,'needs'=>0];foreach($rows as $r){if(($r['source_type']??'')==='fsbo')$stats['fsbo']++;if(($r['priority_band']??'')==='A')$stats['a']++;if(($r['priority_band']??'')==='B')$stats['b']++;if(!empty($r['call_eligible']))$stats['call']++;if(empty($r['owner_phone'])&&empty($r['owner_email']))$stats['needs']++;}$cronKey=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'YOUR_KEY';
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>V14.1 Seller Opportunity Engine</title><style>body{margin:0;background:#f5f3ef;color:#10101a;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.header{background:linear-gradient(135deg,#10101a,#1a1a2e);color:#fff;padding:30px}.brand{font-family:Georgia,serif;color:#c8a96e;font-size:38px}.wrap{max-width:1700px;margin:auto;padding:26px}.grid{display:grid;grid-template-columns:repeat(6,1fr);gap:14px}.kpi,.panel{background:#fff;border-radius:16px;box-shadow:0 2px 12px #0001}.kpi{padding:18px}.n{font-size:28px;font-weight:900}.panel{margin-top:18px;overflow:hidden}.panel h2{font-family:Georgia,serif;margin:0;padding:18px;border-bottom:1px solid #eee}.btn{border:0;display:inline-block;background:#c8a96e;color:#111;text-decoration:none;padding:9px 11px;border-radius:9px;font-weight:900;font-size:12px;margin:2px;cursor:pointer}.light{background:#f2efe8;color:#111}.layout{display:grid;grid-template-columns:1fr .36fr;gap:18px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:11px;border-bottom:1px solid #eee;font-size:14px;vertical-align:top}th{font-size:11px;text-transform:uppercase;color:#777;background:#faf9f6}.muted{color:#777;font-size:13px}pre{white-space:pre-wrap;background:#111;color:#fff;padding:16px;border-radius:12px}input,select,textarea{width:100%;padding:9px;border:1px solid #ddd;border-radius:8px;margin:4px 0}.score{font-size:24px;font-weight:900;color:#c8a96e}@media(max-width:1000px){.grid,.layout{grid-template-columns:1fr}.wrap{padding:14px}}</style></head><body><div class="header"><div class="brand">V14.1 Seller Opportunity Engine</div><div>FSBO, expired, withdrawn, price-reduced and seller-source food for Jessica</div></div><main class="wrap"><?php if($msg):?><div class="panel" style="padding:16px"><?=h($msg)?></div><?php endif;?><p><a class="btn" target="_blank" href="/lead-engine/build-seller-opportunity-engine.php?key=<?=h($cronKey)?>">Build Seller Engine</a><a class="btn light" href="/dashboard/contact-acquisition-center.php">Acquisition</a><a class="btn light" href="/dashboard/opportunity-pipeline.php">Pipeline</a><a class="btn light" href="/dashboard/jessica-master-control.php">Master</a></p><section class="grid"><div class="kpi"><div class="n"><?=h($stats['total'])?></div>Total</div><div class="kpi"><div class="n"><?=h($stats['fsbo'])?></div>FSBO</div><div class="kpi"><div class="n"><?=h($stats['a'])?></div>A</div><div class="kpi"><div class="n"><?=h($stats['b'])?></div>B</div><div class="kpi"><div class="n"><?=h($stats['call'])?></div>Callable</div><div class="kpi"><div class="n"><?=h($stats['needs'])?></div>Needs Contact</div></section><div class="layout"><section class="panel"><h2>Seller Opportunities</h2><table><tr><th>Score</th><th>Source</th><th>Property</th><th>Owner/Contact</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><div class="score"><?=h($r['total_seller_score']??0)?></div><div class="muted"><?=h($r['priority_band']??'')?><br>Intent <?=h($r['seller_intent_score']??0)?></div></td><td><strong><?=h($r['source_type'])?></strong><div class="muted"><?=h($r['source_platform'])?><br><?php if($r['source_url']):?><a target="_blank" href="<?=h($r['source_url'])?>">Open Source</a><?php endif;?></div></td><td><strong><?=h($r['property_address']?:$r['listing_title'])?></strong><div class="muted"><?=h($r['town'])?><br><?=money($r['list_price'])?> list<br><?=money($r['estimated_equity'])?> equity</div></td><td><?=h($r['owner_name'])?><div class="muted"><?=h($r['owner_phone'])?><br><?=h($r['owner_email'])?><br>DNC: <?=h($r['dnc_status'])?><br>Realtor: <?=h($r['realtor_status'])?></div></td><td><?=h($r['recommended_action'])?><form method="post"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn" name="status" value="approved">Approve</button><button class="btn light" name="status" value="source_review">Review</button><button class="btn light" name="status" value="archived">Archive</button></form></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Add Seller Source</h2><div style="padding:16px"><form method="post"><input type="hidden" name="action" value="add"><select name="source_type"><option value="fsbo">FSBO</option><option value="expired">Expired</option><option value="withdrawn">Withdrawn</option><option value="cancelled">Cancelled</option><option value="price_reduced">Price Reduced</option><option value="make_me_move">Make Me Move</option></select><input name="source_platform" placeholder="Zillow / FSBO.com / MLS / Manual"><input name="source_url" placeholder="Source URL"><input name="listing_title" placeholder="Listing title"><input name="property_address" placeholder="Property address"><input name="town" placeholder="Town"><input name="list_price" placeholder="List price"><input name="owner_name" placeholder="Owner name"><input name="owner_phone" placeholder="Owner phone"><input name="owner_email" placeholder="Owner email"><select name="dnc_status"><option value="unchecked">DNC unchecked</option><option value="clear">DNC clear</option><option value="blocked">DNC blocked</option></select><select name="realtor_status"><option value="unchecked">Realtor unchecked</option><option value="clear">Realtor clear</option><option value="match">Realtor match</option></select><select name="approval_status"><option value="source_review">Source review</option><option value="approved">Approved</option></select><textarea name="notes" placeholder="Notes"></textarea><button class="btn">Add Source</button></form></div><h2>Brief</h2><div style="padding:16px"><pre><?=h($brief['briefing_text']??'Build Seller Engine to create briefing.')?></pre></div></section></div></main></body></html>